// seed: tests/seed.expert.spec.ts
// Без пометки устройства: AC3 — про вид на разной ширине (десктоп 1440 + iPhone 375 + Android 412). Только просмотр.
import { test, expect } from '@playwright/test';
import path from 'node:path';
import { SCENARIOS, blockRuleWrites, openExpertScreen, field, cancelConfirmIfShown } from '../helpers/expert';

test.use({ storageState: path.join(__dirname, '../../../auth/expert.json') });

test.describe('Экран «חוקי זיהוי» — эксперт', () => {
  test.afterEach(async ({ page }) => { await cancelConfirmIfShown(page); });

  test('«חוקי זיהוי»: RTL, подписи справа, ни один текст не обрезан, нет горизонтальной прокрутки #89216b @prod-safe', async ({ page }) => {
    const writes = await blockRuleWrites(page);
    await openExpertScreen(page);

    // Документ RTL
    await expect(page.locator('html')).toHaveAttribute('dir', 'rtl');

    // Нет горизонтальной прокрутки страницы — AC3 «שום טקסט לא נחתך»
    const overflowX = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
    expect(overflowX, 'горизонтальная прокрутка страницы').toBeLessThanOrEqual(1);

    // Подпись каждого сценария прижата к правому краю своего поля, текст в поле — RTL — AC3 «מיושרים נכון»
    for (const s of SCENARIOS) {
      const label = page.getByText(s, { exact: true }).filter({ visible: true }).first();
      const input = field(page, s);
      await input.scrollIntoViewIfNeeded();
      const [lb, ib] = [await label.boundingBox(), await input.boundingBox()];
      expect(Math.abs((lb!.x + lb!.width) - (ib!.x + ib!.width)), `«${s}»: правый край подписи = правый край поля (±24)`).toBeLessThanOrEqual(24);
      const dir = await input.evaluate((el) => getComputedStyle(el).direction);
      const align = await input.evaluate((el) => getComputedStyle(el).textAlign);
      expect(dir === 'rtl' || align === 'right', `«${s}»: текст в поле справа (direction=${dir}, text-align=${align})`).toBe(true);
    }

    // Ни один видимый текст не обрезан: у текстовых узлов нет скрытого переполнения (ellipsis/clip) — AC3
    const clipped = await page.evaluate(() => {
      const bad: string[] = [];
      for (const el of Array.from(document.querySelectorAll<HTMLElement>('body *'))) {
        if (!el.childNodes.length || !Array.from(el.childNodes).some((n) => n.nodeType === 3 && n.textContent!.trim())) continue;
        const cs = getComputedStyle(el);
        if (cs.visibility === 'hidden' || cs.display === 'none' || el.offsetParent === null) continue;
        const hidesX = cs.overflowX === 'hidden' || cs.overflowX === 'clip' || cs.textOverflow === 'ellipsis';
        const hidesY = cs.overflowY === 'hidden' || cs.overflowY === 'clip';
        if ((hidesX && el.scrollWidth > el.clientWidth + 1) || (hidesY && el.scrollHeight > el.clientHeight + 1)) {
          bad.push(el.textContent!.trim().slice(0, 60));
        }
      }
      return bad;
    });
    expect(clipped, 'обрезанные тексты').toEqual([]);

    expect(writes.saveCalls).toBe(0);
  });
});
